# Horizontal gapped fill + Vertical beam fill
test_in = [
    [8, 8, 1, 1, 1, 1, 1, 1, 8],
    [8, 8, 1, 8, 1, 8, 8, 8, 8],
    [8, 8, 8, 8, 1, 8, 8, 8, 8],
    [8, 8, 1, 8, 1, 8, 8, 1, 8],
    [8, 8, 1, 8, 1, 8, 8, 1, 8],
    [8, 8, 1, 8, 8, 8, 8, 1, 8],
    [8, 8, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 8, 8, 8, 8],
]

output = [row[:] for row in test_in]

# Step 1: Horizontal gap fill
beam_cols = {2, 7}  # The "main" vertical beams
for r in range(8):
    p_cols = sorted([c for c in range(9) if test_in[r][c] == 1])
    runs = []
    if p_cols:
        cur = [p_cols[0]]
        for x in p_cols[1:]:
            if x == cur[-1] + 1:
                cur.append(x)
            else:
                runs.append(cur)
                cur = [x]
        runs.append(cur)
    for i in range(len(runs) - 1):
        for c in range(runs[i][-1] + 1, runs[i+1][0]):
            output[r][c] = 1

# Step 2: Vertical fill for BEAM columns (2 and 7) - fill from first to last occurrence
for c in beam_cols:
    rows_with_1 = [r for r in range(8) if test_in[r][c] == 1]
    if rows_with_1:
        min_r = min(rows_with_1)
        max_r = max(rows_with_1)
        for r in range(min_r, max_r):
            output[r][c] = 1

print("H + V (beams only):")
for row in output:
    print(" ".join(map(str, row)))

print("\nAs lists:")
for row in output:
    print(row)

# Confirm both approaches give same result

test_in = [
    [8, 8, 1, 1, 1, 1, 1, 1, 8],
    [8, 8, 1, 8, 1, 8, 8, 8, 8],
    [8, 8, 8, 8, 1, 8, 8, 8, 8],
    [8, 8, 1, 8, 1, 8, 8, 1, 8],
    [8, 8, 1, 8, 1, 8, 8, 1, 8],
    [8, 8, 1, 8, 8, 8, 8, 1, 8],
    [8, 8, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 8, 8, 8, 8],
]

output_gap = [row[:] for row in test_in]
output_outer = [row[:] for row in test_in]

# Gap filling
for r in range(8):
    gaps = []
    in_gap = False
    gap_start = None
    for c in range(9):
        has_pattern = test_in[r][c] == 1
        if has_pattern and not in_gap:
            if gap_start is not None:
                gaps.append((gap_start, c - 1))
            in_gap = False
        elif not has_pattern and not in_gap:
            gap_start = c
            in_gap = True
        elif has_pattern and in_gap:
            in_gap = False
            gaps.append((gap_start, c - 1))

    for gap_start, gap_end in gaps:
        has_pattern_before = any(test_in[r][c] == 1 for c in range(gap_start))
        has_pattern_after = any(test_in[r][c] == 1 for c in range(gap_end + 1, 9))
        if has_pattern_before and has_pattern_after:
            for c in range(gap_start, gap_end + 1):
                output_gap[r][c] = 1

# Both-outer
for r in range(8):
    if test_in[r][2] == 1 and test_in[r][7] == 1:
        cols = [c for c in range(9) if test_in[r][c] == 1]
        for c in range(min(cols), max(cols) + 1):
            output_outer[r][c] = 1

print("Gap-filling:")
for row in output_gap:
    print(row)

print("Both-outer:")
for row in output_outer:
    print(row)

print("Equal:", output_gap == output_outer)

